import{_ as s,a}from"./chunks/welcome.Czrg1zlC.js";import{_ as t}from"./chunks/schedule.ZDSBYxh8.js";import{_ as i,o as n,c as l,a3 as o}from"./chunks/framework.CchDE9cb.js";const r="/capacitylens/assets/choose-company.DxAb8PRf.jpg",w=JSON.parse('{"title":"Install CapacityLens","description":"Get a real, persistent CapacityLens install running with password sign-in in about five minutes.","frontmatter":{"title":"Install CapacityLens","description":"Get a real, persistent CapacityLens install running with password sign-in in about five minutes."},"headers":[],"relativePath":"getting-started/install.md","filePath":"getting-started/install.md","lastUpdated":null}'),h={name:"getting-started/install.md"};function p(c,e,d,g,k,u){return n(),l("div",null,[...e[0]||(e[0]=[o(`<h1 id="install-capacitylens" tabindex="-1">Install CapacityLens <a class="header-anchor" href="#install-capacitylens" aria-label="Permalink to &quot;Install CapacityLens&quot;">​</a></h1><p>This is the quick path: four lines of configuration and three screens to a working install with real sign-in, real persistence, and one <a href="/capacitylens/reference/glossary">Owner</a>. It takes about five minutes on a machine that already has Docker or Node installed. For TLS, backups and the full production treatment, see <a href="/capacitylens/self-hosting/">Self-hosting</a> once you&#39;re past this page.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Just want to look around first? <a href="/capacitylens/getting-started/try-the-demo">Try the demo</a> instead — no configuration, no install.</p></div><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Docker, or Node.js with <a href="https://pnpm.io" target="_blank" rel="noreferrer">pnpm</a> — either way to run the app, covered in <a href="/capacitylens/self-hosting/install-with-docker">Install with Docker</a>.</li><li>A way to generate two random strings for the <code>.env</code> file. Run <code>openssl rand -base64 48</code> for each one, or if you don&#39;t have <code>openssl</code>, use a password manager&#39;s password generator set to 32 characters or more.</li></ul><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><p><strong>Fill in the <code>.env</code> file</strong> (~2 minutes). Copy <code>.env.example</code> to <code>.env</code> and set four values:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SMALLSASS_ACCOUNT_MODE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">password</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SMALLSASS_ACCOUNT_SECRET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">random</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> 32+</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> char</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # session signing</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SMALLSASS_ACCOUNT_PUBLIC_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://plan.example.com</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SMALLSASS_ACCOUNT_SETUP_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">random</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> 32+</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> char</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # claims the Owner seat, used once</span></span></code></pre></div><p>All the data lives in one <a href="/capacitylens/reference/glossary">SQLite</a> file next to the app — there&#39;s no separate database to install. See <a href="/capacitylens/self-hosting/install-with-docker">Install with Docker</a> for the full walkthrough of these settings.</p></li><li><p><strong>Start the server.</strong> With Docker:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>See <a href="/capacitylens/self-hosting/install-with-docker">Install with Docker</a> for the full walkthrough, including what each service does. Running Node and pnpm directly instead? See <a href="/capacitylens/self-hosting/install-without-docker">Install without Docker</a>. Once it&#39;s running, visit your URL.</p></li><li><p><strong>Claim the Owner account</strong> (~30 seconds). With an empty database, the sign-in wall becomes a &quot;create the owner account&quot; form: name, email, password, and the setup token from your <code>.env</code>. The moment it succeeds, self-registration closes — nobody else can join your instance without an <a href="/capacitylens/reference/glossary">invite</a>. Every later visit shows the plain sign-in screen instead.</p><p><img src="`+s+'" alt="CapacityLens sign-in screen with email and password fields"></p></li><li><p><strong>Create your company</strong> (~10 seconds). One field. Creating the company also creates its built-in &quot;Internal&quot; client and your Owner <a href="/capacitylens/reference/glossary">membership</a> in the same step.</p><p><img src="'+r+'" alt="Choose a company screen listing Studio North with an Owner badge"></p></li><li><p><strong>Read the 20-second orientation</strong> (~20 seconds). Once per device, CapacityLens explains what it is — and what it isn&#39;t.</p><p><img src="'+a+'" alt="Welcome to CapacityLens dialog explaining it is a resourcing tool, not a project management tool"></p></li><li><p><strong>Start planning.</strong> The schedule opens with a Getting Started panel: add clients, projects and <a href="/capacitylens/reference/glossary">people</a>, then drag out allocations. No sample data is seeded in a real install — what you add is yours.</p><p><img src="'+t+'" alt="The Schedule view with people grouped by discipline, allocation bars, utilisation and a holiday block"></p></li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Don&#39;t rely on <code>admin@admin.admin</code>. It&#39;s a bootstrap account CapacityLens uses only while developers are building the app on their own laptop, and it&#39;s switched off automatically the moment you run a real production install like this one. The Owner account you create in step 3, with your own setup token, is the one that matters — there is no default password to remember or change.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This quick path serves the app on <code>localhost</code>, with no TLS certificate. That&#39;s fine while you&#39;re kicking the tyres, but before you put this install on the internet for real, read <a href="/capacitylens/self-hosting/tls-and-networking">TLS and networking</a>. Real deployments set <code>CAPACITYLENS_HTTPS=1</code> once the public origin is genuinely HTTPS — it&#39;s not needed yet.</p></div><p>If the page is blank or shows an error instead of the sign-in screen, see <a href="/capacitylens/self-hosting/incidents">When something goes wrong</a>.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><p><a href="/capacitylens/getting-started/first-steps">First steps after installing</a> walks through signing in and finding your way around the schedule.</p>',12)])])}const b=i(h,[["render",p]]);export{w as __pageData,b as default};
